  'settings.connections.typeHint': '‘없음’과 ‘직접’은 뜻이 다릅니다. ‘없음’은 아무 일도 하지 않습니다. 어떤 연결도 가리키지 않고 쓰이지도 않으므로, 다 채워 넣을 때까지만 남아 있습니다. ‘직접’은 실제 선택지입니다. 이 기기 자체의 회선으로 나가며, 아래에 적은 호스트에 대해서는 모든 프록시를 건너뜁니다. 앱 전체 프록시에서 NAS를 빼는 방법이 바로 이것입니다. 필터가 호스트와 맞는 행은 필터가 없는 행을 이기므로, 필터가 있는 ‘직접’ 행은 모든 것을 받는 프록시를 항상 이깁니다.',
