  'settings.reconnect.method.upnp': 'UPnP',
  'settings.reconnect.method.script': '스크립트',
  'settings.reconnect.offState': '재연결이 꺼져 있습니다. 공유기에 새 주소를 요청하는 것은 아무것도 없고, 호스트 제한은 평소의 재시도 대기에 맡겨집니다.',

  'settings.reconnect.command': '프로그램',
