  'settings.reconnect.importFailed': '스크립트를 읽지 못했습니다: {reason}',

  'settings.reconnect.checkTitle': '주소 확인',
  'settings.reconnect.checkUrl': 'IP 확인 URL',
  'settings.reconnect.checkUrlHint': '방식을 실행하기 전에 한 번, 실행한 뒤에 다시 한 번 가져오며, 거기 표시되는 주소가 바뀌면 실행이 끝난 것으로 봅니다. 기본값은 없습니다. 직접 운영하는 다운로드 관리자가 고른 적도 없는 서비스에 내 주소를 알리기 시작해서는 안 되기 때문입니다. 표시되는 주소는 인터넷에서 보이는 주소여야 합니다. 내 네트워크 안의 주소를 돌려주는 페이지로는 재연결과 아무 일도 일어나지 않은 경우를 구별할 수 없습니다.',
  'settings.reconnect.checkPresets': '널리 알려진 서비스',
  'settings.reconnect.checkPresetsHint': '특별히 선호하는 곳이 없는 사람을 위한 지름길이지 기본값이 아닙니다. 어느 것도 대신 골라 주지 않으며, 공개 주소를 보여 주는 페이지라면 무엇이든 똑같이 쓸모 있습니다.',
  'settings.reconnect.interval': '확인 간격(초, 1~60)',
  'settings.reconnect.intervalHint': '방식이 실행된 뒤 확인 URL을 두 번 들여다보는 사이에 얼마나 기다릴지입니다. 하한이 있는 이유는, 하한 없는 반복이 확인 서비스를 표적으로 만들기 때문입니다.',
  'settings.reconnect.timeout': '확인을 이어 갈 시간(초, 5~900)',
  'settings.reconnect.timeoutHint': '실행을 실패로 판정하기까지 얼마나 더 지켜볼지입니다. 15분이 지나도 여전히 기다리고 있는 재연결은 여기 무엇이 적혀 있든 실패한 것입니다. 간격보다 짧은 제한 시간은 간격까지 올라갑니다. 그러지 않으면 확인을 한 번도 못 한 채 실행이 끝나 버립니다.',
