  'settings.chunks': '다운로드당 연결 수 (0 = 자동)',
  'settings.chunksHint': '더 구체적인 것이 없을 때 다운로드 하나가 여는 연결 수입니다. 규칙이나 개별 다운로드가 자기 숫자를 지정할 수 있고 이것보다 앞섭니다. 더 적게만 견디는 호스트에는 그래도 더 적게 붙습니다. 호스트 한도는 숫자를 낮출 수만 있고 올리지는 못합니다. 0이면 판단을 앱에 맡깁니다. 파일별로 제한하는 호스트에서는 몇 개를 넘겨도 얻는 것이 없고, 계정이 찍히는 확실한 방법입니다.',
  'task.chunks': '연결 수 (0 = 전역 설정)',
  'task.chunksHint': '이 다운로드 하나가 여는 연결 수입니다. 전역 설정과 그것을 정한 어떤 규칙보다도 앞서지만, 호스트보다 앞서지는 못합니다. 더 적게만 견디는 호스트에는 그래도 더 적게 붙습니다. 0이면 개별 지정이 풀리고 숫자는 다시 밖에서 정해집니다.',
  'columns.connection': '연결',

  'props.title': '속성',
  'props.mixed': '여러 값',
  'props.mixedHint': '이 행들이 서로 달라서 칸이 비어 있습니다. 그대로 두면 아무것도 바뀌지 않고, 입력하면 선택된 모든 행이 입력한 값을 받습니다.',
  'props.name': '이름',
  'props.nameHint': '파일 이름 하나이며 경로는 아닙니다. / 나 \\ 가 들어간 이름은 거부됩니다. 끝난 다운로드는 디스크에서도 이름이 바뀌어 목록과 폴더가 어긋날 수 없습니다. 진행 중인 다운로드는 백엔드가 연 파일을 그대로 쓰고 끝나면 새 이름을 받습니다. 아직 시작하지 않은 다운로드는 바로 새 이름을 받습니다. 이름은 파일 하나의 것이므로 이 칸은 한 행을 골랐을 때만 나옵니다.',
