  'settings.scripts.run': '테스트 실행',
  'settings.scripts.running': '실행 중…',
  'settings.scripts.runNeedsSaveHint': '이름이나 코드를 입력해 스크립트를 만들면 여기서 테스트할 수 있습니다.',
  'settings.scripts.runDirtyHint': '변경 사항을 아직 저장하는 중입니다. 테스트 실행은 잠시 후 그 변경 사항을 사용합니다.',
  'settings.scripts.ranIn': '{duration} 만에 성공적으로 실행됨',
  'settings.scripts.runTimedOut': '중지됨: 시간 제한보다 오래 실행됨',
  'settings.scripts.runFailed': '실패함: {error}',
  'settings.scripts.output': '출력',
  'task.runScript': '스크립트 실행',
  'task.runScriptUnnamed': '제목 없는 스크립트',
  'task.runScriptDone': '"{name}" 실행됨',
  'task.runScriptFailed': '"{name}" 실패함: {error}',
  'settings.access.relay.title': '프로젝트 릴레이',
  'settings.access.relay.body': '릴레이는 중계자로, 모든 인스턴스를 집 네트워크 밖에서도, 즉 어디서든 접근할 수 있게 해 줍니다. 이 릴레이는 프로젝트가 무료로 제공합니다.',
  'settings.access.relay.use': '프로젝트 릴레이 사용',
  'settings.access.relay.leadProject': '설정 없이 작동합니다. 인스턴스끼리 주고받는 내용은 모두 암호화되어 있고, 열쇠는 당신만 가지고 있습니다.',
  'settings.access.relay.seesButton': '무엇이 보이나요?',
  'settings.access.relay.seesTip': '릴레이가 볼 수 없는 것: 링크, 다운로드, 파일, 액세스 토큰.\n\n릴레이가 볼 수 있는 것: 인스턴스의 IP 주소와 무언가를 보내는 시각.\n\n이것은 암호화로 가릴 수 없습니다. 신경 쓰인다면 직접 릴레이를 운영하세요.',
