  'settings.access.phrase.howStep2': '다른 기기에서 KnightLoader를 열고 이 페이지로 와서 "{button}"을(를) 누른 뒤 열두 단어를 입력하세요.',
  'settings.access.phrase.howStep3': '완료했습니다. 이제 각 인스턴스가 서로의 「인스턴스」에 나타나고, 어느 쪽에서든 다른 쪽을 조작할 수 있습니다. 릴레이를 켜 두면 네트워크 바깥에서도 접속할 수 있습니다.',
  'settings.access.phrase.howWhat': '단어는 주소가 아니라 비밀입니다. 각 인스턴스는 그것으로 두 개의 키를 계산합니다. 하나는 서로를 찾기 위한 것이고, 하나는 암호화를 위한 것입니다.\n\n서로를 찾기 위해 각 인스턴스가 스스로 인터넷의 같은 만남 지점을 호출합니다. 같은 키를 보여 준 쪽끼리 연결됩니다. 그래서 어떤 인스턴스도 외부에서 접근 가능할 필요가 없습니다.\n\n만남 지점은 내용을 읽지 못합니다. 당신의 단어를 보는 일은 없고, 그곳을 지나는 모든 것은 두 번째 키로 암호화됩니다.',
