  'settings.resolvers.about': 'yt-dlp 백엔드 설정입니다. 이 백엔드는 yt-dlp 자체가 지원하는 미디어 사이트와 스트리밍 사이트에서 가져옵니다. 어떤 링크를 애초에 어느 서비스가 처리할지(yt-dlp, Debrid 계정, JDownloader 백엔드)는 계정 페이지의 “우선순위”가 정합니다. 이 페이지에서는 링크가 yt-dlp로 넘어온 뒤 yt-dlp가 무엇을 할지 정합니다.',
