  'settings.torrents.portRestartHint': '엔진은 토렌트 클라이언트를 한 번만 만들므로, 새 포트는 이 인스턴스를 다시 시작한 뒤에 적용됩니다. 공유기에 매핑을 요청하는 것은 그 포트에서 토렌트가 이미 대기 중이든 아니든 바로 됩니다.',
  'settings.torrents.portMapHint': '다른 공유기 뒤에 있는 피어도 도달할 수 있도록, 위 포트를 UPnP로 이 기기에 전달하도록 공유기에 요청합니다. 모든 공유기가 이를 지원하지는 않으며, 일부는 실제로 작동하지 않으면서도 요청을 수락합니다.',
  'settings.torrents.portMapButton': 'UPnP 매핑 시도',
  'settings.torrents.portMapping': '공유기에 문의 중…',
  'settings.torrents.portMapNeedsPort': '매핑하기 전에 위에서 포트를 설정하세요. 0이면 공유기가 전달할 대상이 없습니다.',
  'settings.torrents.portMapConfirmed': '확인됨: 포트 {port}가 매핑되었으며 도달 가능함이 확인되었습니다.',
  'settings.torrents.portMapUnconfirmed': '공유기가 요청을 받아들였지만, 매핑이 실제로 작동하는지는 확인하지 못했습니다. 어떤 공유기는 요청을 받아들이기만 하고 실제로는 적용하지 않습니다. 네트워크 바깥에서 연결 확인을 해 보세요.',
  'settings.torrents.portMapFailed': '포트를 매핑하지 못했습니다: {error}',
