  'settings.torrents.networkTitle': '피어 탐색',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': '다른 BitTorrent 클라이언트를 분산 조회 대상으로 사용하여 트래커 없이 피어를 찾습니다.',
  'settings.torrents.pex': '피어 교환 (PEX)',
  'settings.torrents.pexHint': '이미 연결된 피어와 알려진 피어를 교환하여, 피어가 적은 스웜을 더 빨리 찾도록 합니다.',
  'settings.torrents.privateNote': '비공개 토렌트는 메타데이터가 파악되는 즉시, 여기 설정과 관계없이 두 기능을 자동으로 끕니다. 업로드한 .torrent 파일은 곧바로, 마그넷 링크는 스웜에서 자체 메타데이터가 도착하는 즉시 꺼집니다. 대부분의 비공개 트래커는 둘 중 하나라도 사용하는 계정을 차단합니다.',
  'container.noJD': '암호화되어 있어 JDownloader 백엔드만 열 수 있습니다. 설정된 백엔드가 없습니다. 이 인스턴스가 닿을 수 있는 JDownloader를 KL_JD에 설정한 다음 다시 시작하세요.',
