  'settings.torrents.notApplied': '이 빌드는 아래 설정 중 두 가지를 아직 적용하지 않습니다. 업로드 제한은 저장되고 검사도 되지만, 엔진이 실행 중인 다운로드에 적용하지 못합니다. DHT와 PEX도 일반 토렌트에는 닿지 않습니다. 여기서 무엇을 설정하든 둘 다 켠 채로 시드합니다. 비공개 토렌트는 다르게 동작하며, “피어 탐색”의 (i)에서 설명합니다.',
  'onboarding.step': '{total}단계 중 {n}단계',
