  'onboarding.finish': '완료',
  'onboarding.welcome.title': 'KnightLoader에 오신 것을 환영합니다',
  'onboarding.welcome.body': 'KnightLoader는 자체 호스팅 다운로드 관리자입니다. 링크를 붙여넣거나 끌어다 놓으면 알맞은 백엔드가 가져옵니다. 일반 파일 링크는 내장 엔진이, 미디어 페이지는 yt-dlp가, 이미 비용을 내고 있는 호스터는 debrid 서비스가, 그 밖의 모든 것은 헤드리스 JDownloader가 맡습니다. 이 짧은 둘러보기에서는 시작하기 전에 확인해 볼 만한 설정 하나를 다룹니다.',
  'onboarding.welcome.langLabel': '인터페이스 언어',
  'onboarding.folder.title': '파일이 어디에 저장되어야 하나요?',
  'onboarding.folder.body': '완료된 다운로드가 저장되는 폴더입니다. 경로를 입력하거나 서버를 탐색해 고르세요. 일반 설정 페이지에서 언제든지 다시 바꿀 수 있습니다.',
  'onboarding.accounts.title': '원할 때 언제든 사용할 수 있는 프리미엄 호스터',
  'onboarding.accounts.body': '대기열은 계정이 전혀 없어도 작동합니다. 이미 비용을 내고 있는 호스터나 debrid 서비스에서 최대 속도를 원할 때 계정에서 로그인 정보를 추가하세요. 지금 설정해야 할 것은 없습니다.',
  'onboarding.accounts.link': '계정 열기',
