  'settings.nav.shortcuts': '단축키',
  'settings.shortcuts.subtitle': '기본 키보드 단축키가 있는 모든 명령을 적용 위치별로 그룹화했습니다. 바인딩을 변경하거나 기본값으로 재설정하세요.',
