  'settings.resolvers.presetHostHint': '이 기본값이 적용되는 사이트입니다. 예: youtube.com. 소문자로, 앞의 “www.” 없이 저장되며, 주소 전체를 붙여 넣어도 됩니다. 호스트만 남습니다. 큰 동영상 사이트는 항목 하나가 다른 주소도 포함합니다. youtube.com은 youtu.be와 m.youtube.com도 포함합니다. 여기에 항목이 없는 호스터는 모든 변형을 켠 채 최고 품질로 시작합니다.',

