  'settings.feeds.seededHint': '새 구독을 처음 확인할 때는 그 순간 피드에 들어 있는 것을 전부 적어 두기만 하고 하나도 가져오지 않습니다. 게시자의 지난 목록 전체가 한꺼번에 쏟아지지 않게 하기 위해서입니다. 그 뒤에 나타나는 것만 들어옵니다.',
  'settings.feeds.remembered': '기억한 항목 {n}개',
