  'settings.rules.action.category': '카테고리',
  'settings.rules.action.categoryHint': '맞는 링크를 이 페이지 아래쪽 카테고리 목록의 서랍 하나에 넣습니다. 그 서랍은 자기 폴더, 대기열에서의 자리, 압축 풀기 스위치, 이름 충돌 규칙을 함께 가져옵니다. 그대로 두면 어떤 규칙도 이에 대해 아무 말도 하지 않고 링크는 어디에도 들어가지 않습니다. 이 규칙이 저장 폴더까지 지정하면 그 폴더가 이기고, 나머지는 여전히 서랍이 채웁니다. 이미 지운 서랍을 지정하면 저장할 때 거부됩니다. 없는 서랍을 가리키는 규칙은 맞는 모든 링크에 대해 아무 소리 없이 아무 일도 하지 않기 때문입니다.',
