  'detail.addressHint': '이 다운로드를 시작할 때 쓴 주소입니다. 앱이 요청한 곳이며, 바이트가 실제로 온 곳과 늘 같지는 않습니다. Debrid 서비스를 거치면 아래의 호스터는 파일이 놓여 있는 사이트이고, 백엔드는 그것을 가져온 쪽입니다.',
  'detail.copy': '복사',
