  'detail.onDiskHint': '이 순간 디스크에서 이 파일이 차지하는 크기이며, 여기서 세는 것이 아니라 서버에 물어본 값입니다. 실행 중인 다운로드는 한 번 볼 때와 다음에 볼 때 사이에 커지고, 이것은 호스터가 알린 크기가 아닙니다.',
  'detail.mirrorOf': '다음의 예비 사본',
