  'detail.playPartial': '이 다운로드는 아직 끝나지 않았습니다. 디스크에 이미 있는 부분만 재생할 수 있고 그 너머로 건너뛸 수 없으며, 어떤 파일은 마지막 바이트가 도착하기 전까지 아무것도 재생하지 못합니다.',
