  'detail.playRemote': '여기서는 이 인스턴스에 있는 파일만 재생됩니다. 다른 인스턴스는 파일을 통째로, 건너뛰기 없이 넘겨주는데, 재생기는 그것으로는 다룰 수 없습니다.',
