  'notifications.systemBlocked': '브라우저가 이 주소의 알림을 차단하고 있습니다. “시스템 알림”으로 둔 행은 브라우저의 사이트 설정에서 다시 허용할 때까지 앱 안에서 표시됩니다.',
  'notifications.systemNotGranted': '브라우저가 권한을 주지 않았으므로 이 이벤트는 앱 안에 남습니다. 다시 물어보려면 “시스템 알림”을 한 번 더 고르세요.',
