  'views.deleteConfirm': '보기 삭제',
  'views.clearAll': '검색과 모든 필터 지우기',
  'views.clearAllHint': '검색과 필터는 페이지를 떠났다가 돌아와도 그대로 남아 있어서, 떠날 때 보던 목록으로 되돌아옵니다. 이것을 누르면 전체 목록이 다시 나옵니다. 저장된 보기는 건드리지 않습니다.',
  'disk.title': '대상 폴더',
  'disk.hint': '다운로드가 저장될 수 있는 모든 폴더의 여유 공간과 사용 중인 공간, 그리고 대기열이 각 폴더에 아직 써야 할 양입니다. 이 값은 디스크 한도를 검사할 때 쓰는 것과 같은 호출에서 오며, 길어야 몇 초 전의 값입니다. 여유 공간과 사용 중인 공간을 더해도 볼륨 크기가 되지 않을 수 있습니다. 파일 시스템은 일부를 시스템 몫으로 남겨 두고, 사용자별 할당량이 있으면 이 인스턴스가 쓸 수 있는 양이 볼륨에 실제로 남은 것보다 적을 수 있습니다. 같은 디스크에 있는 두 폴더는 각각 그 디스크를 보여 주므로, 행끼리 절대 더하지 마세요.',
  'disk.free': '여유',
  'disk.used': '사용 중',
  'disk.size': '전체 용량',
  'disk.queued': '앞으로 쓸 양',
  'disk.queuedHint': '아직 남은 다운로드가 이 폴더에 더 쓰게 될 양입니다. 호스터가 알린 크기에서 이미 도착한 만큼을 뺀 값입니다. 호스터가 크기를 말해 주지 않는 다운로드는 여기서 0으로 셉니다. 그래서 이 값은 최소치일 뿐 약속이 아니며, 다운로드가 줄줄이 있는 폴더에 0바이트가 적히는 이유이기도 합니다. 꺼 둔 다운로드는 여기 들어가지 않으며, 목록 아래의 숫자와 같은 규칙입니다. 이미 실행 중인 다운로드는 보통 시작하는 순간 디스크에 자리를 잡아 두므로, 그 바이트는 옆의 여유 공간에서 이미 빠져 있고 이 값 위에 다시 더해지지 않습니다.',
  'disk.tasks': '다운로드 {n}개',
  'disk.unknown': '이 시스템은 여유 공간을 알려주지 않습니다',
  'disk.unknownHint': '모든 커널에 볼륨의 남은 공간을 물어볼 수 있는 것은 아니며, 이 빌드에는 지금 실행 중인 커널에 맞는 호출이 없습니다. 답이 없는 곳에서는 아무것도 붙잡지 않습니다. 다운로드는 디스크 한도가 설정되지 않은 것처럼 시작합니다. 이 줄은 정말로 가득 찬 디스크와 구별할 수 있게 하려고 있습니다.',
  'disk.missing': '아직 만들어지지 않음',
  'disk.missingHint': '이 폴더는 첫 파일을 쓰는 쪽이 만들기 때문에 아직 없습니다. 여기 숫자는 그 위에 실제로 있는 가장 가까운 폴더인 {path}를 잰 것이며, 그 폴더는 다운로드가 놓일 디스크에 있습니다.',
  'disk.measured': '{path}에서 측정함',
  'disk.elsewhereHint': '폴더 자체를 잴 수 없어서 그 위에서 잴 수 있는 가장 가까운 폴더를 쟀습니다. 마운트가 올라오지 않았다면 다운로드가 향하는 디스크와 전혀 다른 디스크일 수 있습니다. 숫자에서 무언가를 읽어내기 전에 경로부터 확인하세요.',
  'disk.sampled': '{n}초 전에 읽음',
  'disk.tight': '대기열이 들어가지 않습니다',
  'disk.tightHint': '이 폴더에 써야 할 양이 디스크의 여유 공간보다 많습니다. 이 줄 자체는 아무것도 멈추지 않습니다. 다운로드는 차례가 될 때마다 하나씩, 다운로드 설정 페이지의 숫자에 따라 붙잡힙니다. 그리고 아무도 크기를 모르는 다운로드는 여기서 아예 세지 않습니다.',
  'disk.truncated': '모든 폴더가 여기 있지는 않습니다',
  'disk.truncatedHint': '대기열이 설정된 폴더 바깥의 폴더를 매번 잴 만한 것보다 많이 가리키고 있어서, 써야 할 양이 가장 적은 폴더는 빠졌습니다. 직접 설정한 폴더는 언제나 여기 있습니다.',
  'disk.markLow': '이 아래면 새로 시작하지 않음',
