  'disk.role.task': '다운로드에 직접 지정됨',
  'settings.volume.title': '데이터 한도',
  'settings.volume.titleHint': '이 인스턴스가 다 내려받은 양을 기간마다 직접 정한 한도와 견주어 셉니다. 완료된 다운로드마다 호스터가 알린 크기를 세므로, 크기가 밝혀지지 않은 채 끝난 것은 0으로 세고, 토렌트가 올린 것은 아예 세지 않습니다. 이것은 다운로드를 집계한 값이지 회선을 측정한 값이 아닙니다. 공유기가 실제로 주고받은 바이트는 여기서 아무도 볼 수 없습니다.',
  'settings.volume.cap': '기간당 한도 (GB)',
  'settings.volume.capHint': '0은 한도 없음입니다. 세는 것은 계속되지만 아무것도 붙잡히지 않습니다. 여기서 기가바이트는 10진수이며, 통신사가 제공량을 말할 때와 같은 방식입니다. 500 GB는 500 000 000 000바이트이지 465 GiB가 아닙니다. 이 페이지 위쪽의 디스크 기준값은 2진수 GiB로, 다른 질문을 위한 다른 단위입니다.',
  'settings.volume.resetDay': '숫자가 다시 시작하는 날',
  'settings.volume.resetDayHint': '한 달 중 세던 숫자가 0으로 돌아가는 날이며, 보통은 제공량이 새로 채워지는 날입니다. 고른 날짜보다 짧은 달에는 그달의 마지막 날에 다시 시작하며, 절대 다음 달로 넘어가지 않습니다. 브라우저가 아니라 서버의 시계로 셉니다. 대기열을 붙잡는 것이 서버이기 때문입니다.',
  'settings.volume.action': '한도에 닿았을 때',
  'settings.volume.actionHint': '무엇을 고르든 이미 실행 중인 전송은 중단되지 않습니다. 파일 중간에서 멈추면 이미 쓴 바이트를 버리게 되기 때문입니다. “알리기만 함”은 아무것도 바꾸지 않으며, 카운터가 이 기능의 전부가 됩니다. “새 다운로드를 시작하지 않음”은 실행 중인 것을 끝까지 마치게 하고 카운터가 다시 시작될 때까지 대기열을 붙잡아 두며, 기다리는 행마다 그 사실을 알립니다. “전부 속도 낮추기”는 아래의 속도로 대기열을 계속 진행합니다.',
  'settings.volume.actionReport': '알리기만 함',
  'settings.volume.actionPause': '새 다운로드를 시작하지 않음',
  'settings.volume.actionThrottle': '전부 속도 낮추기',
  'settings.volume.throttle': '상한 도달 후 속도',
  'settings.volume.throttleHint': '기간의 남은 동안 적용되는 속도입니다. 다른 제한을 대신하는 것이 아니라 그 옆에 놓이는 상한이므로, 더 낮은 값을 요구하는 야간 창이나 무음 모드가 그대로 이깁니다. 여기서 0은 제한이 전혀 없다는 뜻이라 한도가 없는 것과 같으므로, 쓸모 있는 가장 작은 숫자는 1입니다.',
  'settings.volume.noCap': '한도 없음',
  'settings.volume.used': '이 기간에 받은 양',
  'settings.volume.usedOf': '{cap} 중 {used}',
  'settings.volume.resetsOn': '{date}에 다시 시작',
  'settings.volume.reached': '한도에 닿았습니다.',
  'volume.title': '내려받은 데이터양',
  'volume.titleHint': '다운로드 히스토리에서 가져온 완료된 다운로드를 날짜별과 달별로 더한 값입니다. 히스토리에는 자체 상한이 있고 직접 비울 수도 있으므로, 그 끝에서 밀려난 달은 여기에 그냥 없습니다. 다시 시작한 다운로드는 마지막으로 완료된 날에 한 번만 셉니다. 달력은 서버의 것이며 {zone} 기준입니다.',
  'volume.range.days': '30일',
  'volume.range.months': '12개월',
  'volume.split.total': '전체',
  'volume.split.host': '호스터별',
  'volume.split.backend': '백엔드별',
  'volume.other': '그 밖의 전부',
  'volume.empty': '이 기간에는 아직 완료된 것이 없습니다.',
  'volume.unsizedHint': '이 중 {n}개의 다운로드는 호스터가 끝내 크기를 밝히지 않은 채 끝났습니다. 합계에 아무것도 더하지 않으므로 실제 값은 여기 그려진 것보다 큽니다.',
  'volume.trimmedHint': '히스토리가 자체 상한에 닿아 있어서, 가장 오래된 항목보다 이전의 것은 이 곡선에도 없습니다. 더 멀리까지 남기고 싶다면 이 페이지에서 히스토리 상한을 높이세요.',
  'volume.meter': '데이터양',
  'volume.meterHint': '카운터가 마지막으로 다시 시작된 뒤 다운로드가 끝난 양이며, 다운로드 설정 페이지의 한도와 비교합니다. 이 숫자는 다운로드가 끝날 때 움직이며, 진행 중에는 움직이지 않습니다. 다운로드 기록에서 합산하므로, 기록을 비우면 이 카운터도 0으로 돌아갑니다.',
