  'events.title': '이벤트',
  'events.open': '이벤트 목록 열기',
  'events.titleHint': '이 창이 보여 주는 모든 알림은 여기에도 남습니다. 그래서 말풍선이 이미 사라진 알림도 다시 읽을 수 있습니다. 마지막 {max}개까지 보관하며, 페이지를 새로 불러올 때마다 목록은 처음부터 다시 시작합니다.',
