  'settings.shortcuts.listTitle': '목록의 키',
  'settings.shortcuts.listHint': '이 키들은 다운로드 목록과 수집함 목록에 속하며 다시 바인딩할 수 없습니다. 행이 포커스를 가진 동안에만 동작하므로, 위에 있는 명령에서 키를 빼앗는 일은 없습니다.',
