  'settings.owner.v.missing': '그 폴더가 없습니다. 처음으로 무언가가 그 안에 기록될 때 만들어집니다.',
  'settings.owner.v.unknown': '이 시스템에서는 파일에 소유자가 없으므로 여기서는 비교할 것이 없습니다. 이것은 오류가 아닙니다.',
  'settings.owner.fix.user': '폴더의 주인인 계정으로 컨테이너를 시작하세요. 실행 명령의 --user {dirUid}:{dirGid} 부분입니다. Unraid에서는 Extra Parameters에 들어갑니다.',
  'settings.owner.fix.chown': '아니면 폴더 쪽을 넘기세요. 호스트에서: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': '그것은 이 인스턴스가 바꿀 수 없습니다. 마스크는 컨테이너를 시작한 쪽에서 오고, 마운트된 공유는 umask, file_mode, dir_mode 옵션으로 자기 것을 강제할 수 있습니다. 폴더가 마운트되는 자리에서 고치세요.',
  'settings.owner.fix.recreate': '실행 명령을 바꿨다면 컨테이너를 새로 만들어야 합니다. 다시 시작하는 것만으로는 부족합니다. 신원은 컨테이너가 시작하는 순간 정해지기 때문입니다.',
  'settings.owner.fix.past': '이미 내려받은 파일은 기록될 때 받은 소유자를 그대로 지닙니다. 당신이 바꾸는 것은 앞으로 오는 것에 적용되고, 나머지는 위의 명령이 있어야 합니다.',
  'settings.selftest.title': '자체 점검',
  'settings.selftest.hint': '이 인스턴스가 스스로에 대해 알아낼 수 있는 모든 것입니다. JDownloader 백엔드, yt-dlp, 폴더, Debrid 로그인, 릴레이, 시계를 살펴봅니다. 모두 이 기기에서 실행됩니다. 밖으로 나가는 것은 Debrid 로그인뿐이며, 이는 당신이 설정한 제공자에게 갑니다.',
