  'settings.selftest.jd.provisioningOff': '프로비저닝이 꺼져 있고 주소도 설정되어 있지 않아서, 연결할 백엔드가 없습니다.',
  'settings.selftest.jd.missing': '백엔드 주소가 없습니다. 암호화된 DLC와 컨테이너 링크는 거부됩니다.',
  'settings.selftest.jd.missingAdvice': '이 빌드는 보통 시작하면서 자기 헤드리스 JDownloader를 띄우고 KL_JD를 스스로 채웁니다. 그것이 비어 있다는 것은 그 시작이 실패했다는 뜻입니다. 아래쪽 로그에서 "JD provisioning failed"를 찾아보거나, KL_JD를 당신 자신의 JDownloader로 설정하세요.',
  'settings.selftest.jd.unreachable': '{address} 주소가 응답하지 않았습니다.',
  'settings.selftest.jd.unreachableAdvice': '주소는 저장되어 있지만 그 주소에서 대기 중인 것이 없습니다. 백엔드가 실행 중인지, 그리고 그 포트 3128에 호스트에서만이 아니라 이 컨테이너 안에서도 닿을 수 있는지 확인하세요.',
  'settings.selftest.jd.noVersion': '응답은 하지만, 어느 리비전인지는 말해 주지 않습니다.',
  'settings.selftest.ytdlp': 'yt-dlp',
