  'settings.selftest.folders.notWritable': '{dir} 폴더에는 쓸 수 없습니다.',
  'settings.selftest.folders.notWritableAdvice': '이 프로세스는 uid {uid} 계정으로 실행됩니다. 호스트에서 그 폴더가 누구의 것인지, 그리고 그 uid가 그 안에 쓸 수 있는지 살펴보세요.',
