  'settings.selftest.folders.missingAdvice': '아직 아무것도 기록되지 않은 폴더라면 정상이고, 첫 다운로드가 그 폴더를 만듭니다. 다만 {measured} 경로가 볼륨의 뿌리라면 기대하던 마운트가 빠진 것이고, 다운로드는 당신의 디스크가 아니라 컨테이너 안에 들어갑니다.',
  'settings.selftest.folders.low': '{dir} 폴더에는 {free} 공간만 남았고, 이는 대기열이 멈추는 기준값 {mark} 아래입니다.',
  'settings.selftest.folders.noMark': '{dir} 폴더에 {free} 공간이 남았습니다. 고정 기준값을 정해 두지 않았으므로, 대기열은 지금 상태로도 들어가지 못하는 다운로드만 붙잡아 둡니다.',
  'settings.selftest.folders.unknown': '이 플랫폼에서는 {dir} 폴더에 공간이 얼마나 있는지 물어볼 수 없습니다.',
