  'auth.twoFactor.needsPassword': '먼저 비밀번호를 정하세요. 2단계 인증은 비밀번호를 지키는 것이므로 비밀번호가 있어야 합니다.',
  'auth.twoFactor.beforeYouStart': '설정 마지막에 복구 코드 여덟 개가 나옵니다. 한 번만 보이고 다시는 보이지 않습니다. 시작하기 전에 적어 둘 곳을 마련하세요.',
