  'auth.twoFactor.codesTitle': '지금 적어 두세요',
  'auth.twoFactor.codesHint': '보이는 것은 이번 한 번뿐입니다. 각 코드는 앱 코드 대신 한 번씩 쓸 수 있고, 휴대폰을 잃었을 때 다시 들어올 수 있는 유일한 수단입니다.',
  'auth.twoFactor.codesAck': '적어 두었습니다',
