  'auth.twoFactor.verify': '계속',
  'auth.twoFactor.codeWrong': '이 코드는 받아들여지지 않았습니다.',
  'auth.passkey.title': '패스키',
  'auth.passkey.hint': '휴대폰, 노트북, 보안 키가 가진 열쇠로 비밀번호를 치지 않고 로그인합니다. 들어오는 길이 하나 더 생기는 것뿐이라 비밀번호는 계속 쓸 수 있고, 패스키를 모두 지워도 아무도 갇히지 않습니다. 패스키는 만들어진 웹 주소에 속하므로, 프록시를 통해 등록한 것은 로컬 네트워크 주소에서 작동하지 않고 그 반대도 마찬가지입니다.',
  'auth.passkey.registered': '{n} 개 등록됨',
