  'auth.passkey.needsPassword': '먼저 비밀번호를 정하세요. 패스키는 로그인으로 가는 두 번째 길이므로 로그인이 있어야 합니다.',
  'auth.passkey.unavailableTitle': '패스키에는 호스트 이름이 필요한데, 이 페이지는 IP 주소로 열려 있습니다.',
  'auth.passkey.unavailableReason': '패스키는 도메인에 묶여 있어서 브라우저는 맨 주소에서는 교환 전체를 거부하고, 신뢰하지 않는 인증서에서도 다시 거부합니다. 진짜 이름과 유효한 인증서를 갖춘 리버스 프록시를 통해 KnightLoader 에 접속하고, 거기서 열어 그 주소에 열쇠를 등록하세요.',
  'auth.passkey.noBrowserTitle': '이 브라우저는 패스키를 제공하지 않습니다.',
