  'auth.passkey.error.otherAddress': '이 설정은 다른 주소에서 시작되었습니다. 열쇠가 작동해야 할 주소로 KnightLoader를 열고, 거기서 다시 시작하세요.',
  'settings.stall.reconnect': '정체된 다운로드에 새 연결 열기',
  'settings.stall.reconnectHint': '표시된 다운로드의 연결을 닫고 파일의 나머지를 요청하는 새 연결을 엽니다. 다운로드는 이미 받은 것과 자리를 유지하므로, 끌 때까지 켜져 있습니다. 파일을 통째로만 보낼 수 있는 서버는 처음부터 다시 보냅니다. 이것이 없으면 파일 중간에 서버가 응답을 멈춘 다운로드는 누군가 일시 중지할 때까지 0 B/s에 머뭅니다. 다운로드가 멈춰 있는 동안 위에서 정한 시간이 지날 때마다 이 일이 반복됩니다. “정체된 다운로드를 처음부터 다시 시작”도 켜져 있으면, 새 연결 뒤에도 그만큼 멈춰 있는 다운로드는 처음부터 다시 시작합니다. 새 연결은 내장 엔진의 다운로드만 받으며, debrid와 TorBox 다운로드도 포함됩니다. JDownloader와 yt-dlp는 자기 연결을 스스로 관리하고, 피어가 없는 토렌트에는 새 연결도 도움이 되지 않으므로 표시만 합니다.',
  'props.backend': '서비스',
  'props.backendAuto': '자동',
  'props.backendHint': '이 링크를 받을 서비스입니다. “자동”은 계정 페이지의 우선순위에서 지금 링크를 받을 수 있는 첫 서비스를 고릅니다. 고정한 링크는 그 서비스로만 가고, 서비스가 받을 수 없으면 이유와 함께 실패합니다. 진행 중인 다운로드는 지금 서비스에 남습니다. 일시 중지된 다운로드는 다시 시작하면 옮겨 가고 그곳에서 처음부터 시작합니다.',
  'settings.globalSpeedLimit': '속도 제한 (0 = ∞)',
