  'collector.toastStartHeld': '{n} link(s) are held back and were not started.',
  'torrent.held': '{file} was held back: {reason}',
  'collector.filtered.heldSummary': '{n} link(s) held back',
  'collector.filtered.heldInfo': 'Links a link filter rule refused, and torrents that announce a banned tracker. They are kept here instead of in the list above, so a working filter does not leave the collector looking full of junk. Nothing was lost. Restore puts a link back and lets it past the rule or ban that caught it, for when that turned out to be too broad. Clear deletes it. Either way, no file has been downloaded.',
  'collector.filtered.toastHeldBack': 'Staged {n} link(s); {held} held back',
  'collector.filtered.toastAllHeldBack': 'Nothing was staged: {held} link(s) held back',
  'settings.torrents.filesHint': 'Chooses which files of a torrent are fetched when nobody chose them by hand. For a magnet link that happens once its file list has arrived. A .torrent opens its file list with this choice ticked, and it applies if you add the torrent without changing it. Whatever you tick or untick yourself always wins. If nothing would be left, every file is fetched. A category can have its own file selection instead.',
  'settings.torrents.extraTrackersHint': 'One tracker address per line, added to torrents so they find more peers. A .torrent marked private never gets them. A magnet link only says whether it is private once its file list has arrived, and by then the trackers are already added, so a magnet whose own tracker address carries a passkey gets none either. A private tracker that knows you by your IP address rather than a passkey cannot be spotted this way: leave this empty if you get magnet links from one.',
  'settings.torrents.bannedTrackersHint': 'One host name or tracker address per line; its subdomains count too. A torrent that announces to one of them is not added: the collector holds it back with the reason, like a link the link filter refuses. Restoring it there lets it past the line that caught it, not past one you add later. A banned tracker is never added as an extra tracker either.',
  'detail.heldBecause': 'Held back because',
  'settings.categories.torrentFiles': 'Torrent file selection',
  'settings.categories.torrentFilesHint': 'Which files of a torrent filed here are fetched when nobody ticked them by hand. Inherit uses the file selection on the Torrents page. Own replaces it for this category, for example a music category where the small files are the album. It applies when the torrent starts, so it also covers a torrent a Packagizer rule files here. Files you tick yourself always win.',
  'settings.categories.torrentFilesOwn': 'Own',
  'settings.watchDirFilesHint': 'Files dropped here are picked up automatically: link lists (.txt, .crawljob, .magnet), .torrent files, containers (.dlc, .ccf, .rsdf) and .nzb files.',
  'container.usenet': '{file} went to {service}. Its files appear here once {service} has fetched them from Usenet.',
  'settings.help.intake.watchFiles': 'A watch folder picks up what is dropped into it: link lists (.txt, .crawljob, .magnet), .torrent files, containers (.dlc, .ccf, .rsdf) and .nzb files.',
  'container.nzbTooBig': 'it is larger than {max}, the most an .nzb may be',
  'container.noUsenet': 'it is an .nzb, and those are fetched from Usenet through a TorBox or Premiumize.me account. None of your accounts can do that: add one under Accounts.',
  'activity.usenet': 'Usenet',
  'settings.help.intake.nzb': 'An .nzb, uploaded here or sent by Sonarr or Radarr, goes to your TorBox or Premiumize.me account, which fetches it from Usenet. Its files then download like any other link.',
  'task.remote': 'Fetching on {service}',
  'task.remoteSeeds': 'Seeds: {n}',
  'accounts.routing.orderHintTorrents': 'Magnet links and .torrent files go either to Torrent and magnet, the built-in client, or to a debrid service that takes torrents, whichever is higher in the list.',
  'accounts.routing.tip.torrent': 'The built-in torrent client. A debrid service that takes torrents and sits above this row fetches magnet links and .torrent files instead.',
  'settings.torrents.debridTitle': 'Through a debrid service',
  'settings.torrents.debridHint': 'TorBox, Real-Debrid, AllDebrid, Premiumize.me and Debrid-Link can fetch magnet links and .torrent files instead of the built-in client. The service downloads the torrent to its own servers, and KnightLoader then fetches the files from there like any other link. Nothing seeds from this machine and your address never appears in a swarm, so no port needs to be open. A torrent the service already has is ready at once. The priority order on the Accounts page decides whether a debrid service or the built-in client goes first. A torrent from a private tracker always stays with the built-in client. The file selection on this page chooses the files here too: Real-Debrid and Debrid-Link fetch only those, and from the other services only those come here.',
  'accounts.col.import': 'Import',
  'task.remoteHint': '{service} is downloading this to its own servers and has {percent} so far. The files come here once it has all of them.',
  'settings.modules.detail.torrentsOffDebrid': 'Off. Running torrents carry on and keep seeding. New ones go to a debrid service that takes torrents.',
  'collector.filtered.origin.account': 'debrid account',
  'accounts.importAccount': 'Import from {account}',
  'accounts.importHint': 'KnightLoader reads the service\'s list once a minute and brings in whatever was added there since you switched this on: torrents, and from TorBox and Premiumize.me also web and usenet downloads. They land in the link collector like any other link and are fetched from this account. Nothing KnightLoader added itself comes in. The service does not say who added a download, so whatever another app adds with the same account comes in as well. Leave this off for an account that rdt-client or a second KnightLoader also uses. Once its files are here, or when you remove it here, a download is deleted on the service unless Settings, Torrents keeps downloads there. A dash means the service has no list KnightLoader can read.',
  'settings.torrents.keepOnService': 'Keep downloads on the debrid service',
  'settings.torrents.keepOnServiceHint': 'When this is off, KnightLoader deletes a torrent from the debrid service once all its files are here, and does the same with a download imported from the account, so neither piles up against the account\'s limits. An imported download you remove here before it has finished is deleted there too. When this is on, both stay on the service, for example so you can stream them from there later. A torrent KnightLoader added is deleted either way if you remove it before it has finished, and one the account already had is never deleted.',
